import type { ToggleButtonProps } from "../toggle-button.types";
import type { ButtonProps } from "@components/button";
import type { IconButtonProps } from "@components/icon-button";

import React, { useState, useCallback, useRef, useEffect } from "react";

export const useToggleButton = ({
  disabled,
  selected: controlledSelected,
  defaultSelected,
  onValueChange,
  children,
  variant: buttonVariant,
  size: buttonSize,
}: Partial<ToggleButtonProps>): {
  role: string;
  handleKeyDown: (event: React.KeyboardEvent) => void;
  renderChildren: () => React.ReactNode;
} => {
  const [internalSelected, setInternalSelected] = useState<string>(defaultSelected ?? "");
  const [focusedIndex, setFocusedIndex] = useState<number>(-1);
  const isControlled = controlledSelected !== undefined;
  const selected = isControlled ? controlledSelected : internalSelected;

  const buttons = React.Children.toArray(children).filter(
    React.isValidElement,
  ) as React.ReactElement<ButtonProps | IconButtonProps>[];
  const buttonRefs = useRef<(HTMLButtonElement | null)[]>([]);
  buttonRefs.current = buttons.map((_, index) => buttonRefs.current[index] || null);

  const hasMounted = useRef(false);
  useEffect(() => {
    if (!hasMounted.current) {
      hasMounted.current = true;
      return;
    }
    onValueChange?.(controlledSelected);
  }, [controlledSelected, onValueChange]);

  const handleButtonClick = useCallback(
    (value?: string) => {
      if (!value || value === selected) return;

      const newSelected = value;

      if (!isControlled) {
        setInternalSelected(newSelected);
      }
      onValueChange?.(newSelected);
    },
    [selected, isControlled, onValueChange],
  );

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent) => {
      let newIndex = focusedIndex;

      const findNextEnabledIndex = (startIndex: number, direction: 1 | -1) => {
        let currentIndex = startIndex;
        do {
          currentIndex = (currentIndex + direction + buttons.length) % buttons.length;
          const buttonElement = buttonRefs.current[currentIndex];
          if (!buttonElement?.disabled) return currentIndex;
        } while (currentIndex !== startIndex);
      };

      switch (event.key) {
        case "ArrowRight":
        case "ArrowDown":
          newIndex = Number(findNextEnabledIndex(focusedIndex, 1));
          break;
        case "ArrowLeft":
        case "ArrowUp":
          newIndex = Number(findNextEnabledIndex(focusedIndex, -1));
          break;
        case "Home":
          newIndex = Number(findNextEnabledIndex(-1, 1));
          break;
        case "End":
          newIndex = Number(findNextEnabledIndex(buttons.length, -1));
          break;
        default:
          return;
      }

      event.preventDefault();
      setFocusedIndex(newIndex);
      buttonRefs.current[newIndex]?.focus();
    },
    [focusedIndex, buttons],
  );

  const renderChildren = () =>
    React.Children.map(children, (child, index) => {
      if (!React.isValidElement(child)) return child;

      const value = child.props.value;
      const isSelected = selected === value;
      const isFocused = index === focusedIndex;
      const isLastSelected = isSelected && selected !== "";
      const childDisplayName = (child.type as { displayName?: string }).displayName;

      const baseProps: Partial<ButtonProps | IconButtonProps> = {
        size: child.props.size || buttonSize,
        variant: child.props.variant || buttonVariant,
        buttonType:
          child.props.buttonType || (childDisplayName === "IconButton" ? "primary" : "tertiary"),
      };

      const props = {
        ...baseProps,
        disabled: child.props.disabled || disabled,
        selected: isSelected,
        "data-selected": isSelected || undefined,
        "data-last-selected": isLastSelected,
        onClick: () => handleButtonClick(value),
        role: "radio",
        "aria-checked": isSelected,
        tabIndex: isFocused || focusedIndex === -1 ? 0 : -1,
        onFocus: () => setFocusedIndex(index),
        ref: (instance: HTMLButtonElement) => {
          buttonRefs.current[index] = instance;
        },
      };

      return React.cloneElement(child, props);
    });

  return {
    role: "radiogroup",
    handleKeyDown,
    renderChildren,
  };
};
